'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var incrmminmax = require( '@stdlib/stats/incr/mminmax' );


// MAIN //

/**
* Returns an accumulator function which incrementally computes moving minimum and maximum values, ignoring `NaN` values.
*
* @param {Collection} [out] - output array
* @param {PositiveInteger} window - window size
* @throws {TypeError} output argument must be array-like
* @throws {TypeError} window size must be a positive integer
* @returns {Function} accumulator function
*
* @example
* var accumulator = incrnanmminmax( 3 );
*
* var mm = accumulator();
* // returns null
*
* mm = accumulator( 2.0 );
* // returns [ 2.0, 2.0 ]
*
* mm = accumulator( -5.0 );
* // returns [ -5.0, 2.0 ]
*
* mm = accumulator( NaN );
* // returns [ -5.0, 2.0 ]
*
* mm = accumulator( 5.0 );
* // returns [ -5.0, 5.0 ]
*
* mm = accumulator();
* // returns [ -5.0, 5.0 ]
*/
function incrnanmminmax( out, window ) {
	var mminmax;
	if ( arguments.length === 1 ) {
		mminmax = incrmminmax( out );
	} else {
		mminmax = incrmminmax( out, window );
	}
	return accumulator;

	/**
	* If provided a value, the accumulator function returns updated minimum and maximum values. If not provided a value, the accumulator function returns the current minimum and maximum values.
	*
	* @private
	* @param {number} [x] - new value
	* @returns {(ArrayLikeObject|null)} min/max array or null
	*/
	function accumulator( x ) {
		if ( arguments.length === 0 || isnan( x ) ) {
			return mminmax();
		}
		return mminmax( x );
	}
}


// EXPORTS //

module.exports = incrnanmminmax;
